import base64
import os
from dataclasses import dataclass
from typing import Any, Dict, Optional, Union

import boto3
from botocore.exceptions import BotoCoreError, ClientError


@dataclass
class EnvelopeEncryptedPayload:
    kms_key_id: str
    encrypted_data_key: str
    nonce: str
    ciphertext: str
    encryption_context: Optional[Dict[str, str]] = None


class AWSEnvelopeEncryption:
    """
    Envelope encryption using AWS KMS for wrapping a locally generated data key.

    Uses:
      - AWS KMS encrypt/decrypt via boto3
      - AES-GCM for bulk data encryption
    """

    def __init__(self, kms_key_id: str, region_name: Optional[str] = None):
        self.kms_key_id = kms_key_id
        self.kms = boto3.client("kms", region_name=region_name)

    @staticmethod
    def _b64encode(data: bytes) -> str:
        return base64.b64encode(data).decode("utf-8")

    @staticmethod
    def _b64decode(data: Union[str, bytes]) -> bytes:
        if isinstance(data, bytes):
            data = data.decode("utf-8")
        return base64.b64decode(data)

    @staticmethod
    def _normalize_plaintext(data: Union[str, bytes]) -> bytes:
        if isinstance(data, bytes):
            return data
        return data.encode("utf-8")

    def generate_data_key(self, encryption_context: Optional[Dict[str, str]] = None) -> Dict[str, bytes]:
        kwargs: Dict[str, Any] = {"KeyId": self.kms_key_id, "KeySpec": "AES_256"}
        if encryption_context:
            kwargs["EncryptionContext"] = encryption_context

        try:
            response = self.kms.generate_data_key(**kwargs)
            return {
                "plaintext_key": response["Plaintext"],
                "encrypted_key": response["CiphertextBlob"],
            }
        except (BotoCoreError, ClientError) as e:
            raise RuntimeError(f"Failed to generate data key with AWS KMS: {e}") from e

    def encrypt(
        self,
        plaintext: Union[str, bytes],
        encryption_context: Optional[Dict[str, str]] = None,
    ) -> EnvelopeEncryptedPayload:
        try:
            from cryptography.hazmat.primitives.ciphers.aead import AESGCM
        except ImportError as e:
            raise ImportError("cryptography package is required for AES-GCM encryption") from e

        plaintext_bytes = self._normalize_plaintext(plaintext)
        key_material = self.generate_data_key(encryption_context=encryption_context)
        aesgcm = AESGCM(key_material["plaintext_key"])

        nonce = os.urandom(12)
        associated_data = None
        if encryption_context:
            associated_data = self._serialize_context(encryption_context)

        ciphertext = aesgcm.encrypt(nonce, plaintext_bytes, associated_data)

        return EnvelopeEncryptedPayload(
            kms_key_id=self.kms_key_id,
            encrypted_data_key=self._b64encode(key_material["encrypted_key"]),
            nonce=self._b64encode(nonce),
            ciphertext=self._b64encode(ciphertext),
            encryption_context=encryption_context,
        )

    def decrypt(
        self,
        payload: Union[EnvelopeEncryptedPayload, Dict[str, Any]],
    ) -> bytes:
        try:
            from cryptography.hazmat.primitives.ciphers.aead import AESGCM
        except ImportError as e:
            raise ImportError("cryptography package is required for AES-GCM decryption") from e

        if isinstance(payload, dict):
            payload = EnvelopeEncryptedPayload(**payload)

        encrypted_key = self._b64decode(payload.encrypted_data_key)
        nonce = self._b64decode(payload.nonce)
        ciphertext = self._b64decode(payload.ciphertext)

        decrypt_kwargs: Dict[str, Any] = {"CiphertextBlob": encrypted_key}
        if payload.encryption_context:
            decrypt_kwargs["EncryptionContext"] = payload.encryption_context

        try:
            response = self.kms.decrypt(**decrypt_kwargs)
            plaintext_key = response["Plaintext"]
        except (BotoCoreError, ClientError) as e:
            raise RuntimeError(f"Failed to decrypt data key with AWS KMS: {e}") from e

        aesgcm = AESGCM(plaintext_key)
        associated_data = None
        if payload.encryption_context:
            associated_data = self._serialize_context(payload.encryption_context)

        try:
            plaintext = aesgcm.decrypt(nonce, ciphertext, associated_data)
        except Exception as e:
            raise RuntimeError(f"Failed to decrypt payload: {e}") from e

        return plaintext

    @staticmethod
    def _serialize_context(context: Dict[str, str]) -> bytes:
        items = sorted((str(k), str(v)) for k, v in context.items())
        return "&".join(f"{k}={v}" for k, v in items).encode("utf-8")
